// PACore: the Rust core (pa-ffi) for Swift via UniFFI (ADR-0001, CORE-003).
// PACoreFFI.xcframework and Sources/PACore/PACore.swift are generated by
// tools/bindings/build-xcframework.sh and are not committed.
import PackageDescription

let package = Package(
    name: "PACore",
    // Keep in sync with the *_DEPLOYMENT_TARGET values in build-xcframework.sh.
    platforms: [.iOS(.v15), .tvOS(.v15), .macOS(.v12)],
    products: [
        .library(name: "PACore", targets: ["PACore"]),
    ],
    targets: [
        // Static libpa_ffi.a per platform + C header and module map `PACoreFFI`.
        .binaryTarget(name: "PACoreFFI", path: "PACoreFFI.xcframework"),
        // UniFFI Swift wrapper: `import PACore` gives `coreVersion()` and the rest.
        .target(
            name: "PACore",
            dependencies: ["PACoreFFI"],
            path: "Sources/PACore",
            exclude: [".gitkeep"]
        ),
        .testTarget(name: "PACoreTests", dependencies: ["PACore"], path: "Tests/PACoreTests"),
    ]
)
